import os
import re
import hashlib
import hmac
import secrets
import mimetypes
import sqlite3
from functools import wraps
from flask import Flask, request, jsonify, send_file, g, abort
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', secrets.token_hex(32))
app.config['UPLOAD_DIR'] = '/var/app/uploads'
app.config['MAX_CONTENT_LENGTH'] = 10 * 1024 * 1024

ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.gif', '.doc', '.docx'}
BLOCKED_PATTERNS = re.compile(r'(\.\.|%2e%2e|%252e|\x2e)', re.IGNORECASE)

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect('/var/app/files.db')
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect('/var/app/files.db')
    db.executescript('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            api_key_hash TEXT NOT NULL,
            storage_quota INTEGER DEFAULT 52428800,
            is_active INTEGER DEFAULT 1
        );
        CREATE TABLE IF NOT EXISTS files (
            id INTEGER PRIMARY KEY,
            owner_id INTEGER NOT NULL,
            filename TEXT NOT NULL,
            storage_path TEXT NOT NULL,
            file_size INTEGER NOT NULL,
            content_hash TEXT NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            is_public INTEGER DEFAULT 0,
            FOREIGN KEY (owner_id) REFERENCES users(id)
        );
        CREATE TABLE IF NOT EXISTS shares (
            id INTEGER PRIMARY KEY,
            file_id INTEGER NOT NULL,
            shared_with_id INTEGER NOT NULL,
            permission TEXT DEFAULT 'read',
            FOREIGN KEY (file_id) REFERENCES files(id),
            FOREIGN KEY (shared_with_id) REFERENCES users(id)
        );
        CREATE INDEX IF NOT EXISTS idx_files_owner ON files(owner_id);
        CREATE INDEX IF NOT EXISTS idx_shares_user ON shares(shared_with_id);
    ''')
    db.commit()
    db.close()

def authenticate(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key or len(api_key) != 64:
            return jsonify({'error': 'Authentication required'}), 401
        key_hash = hashlib.sha256(api_key.encode()).hexdigest()
        db = get_db()
        user = db.execute(
            'SELECT id, username, storage_quota, is_active FROM users WHERE api_key_hash = ?',
            (key_hash,)
        ).fetchone()
        if not user or not user['is_active']:
            return jsonify({'error': 'Invalid or inactive API key'}), 401
        g.user = dict(user)
        return f(*args, **kwargs)
    return decorated

def validate_filename(filename):
    """Validate filename for safety."""
    if not filename or len(filename) > 255:
        return None
    if BLOCKED_PATTERNS.search(filename):
        return None
    # Use werkzeug's secure_filename for sanitization
    safe_name = secure_filename(filename)
    if not safe_name:
        return None
    # Verify extension is allowed
    _, ext = os.path.splitext(safe_name)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return None
    return safe_name

def resolve_storage_path(user_id, filename):
    """Resolve the full storage path for a file.

    Constructs path: UPLOAD_DIR / user_id / filename
    Validates the resolved path is within the user's directory.
    """
    user_dir = os.path.join(app.config['UPLOAD_DIR'], str(user_id))
    # Construct full path
    full_path = os.path.join(user_dir, filename)
    # Normalize to resolve any remaining path components
    normalized = os.path.normpath(full_path)
    # Security check: ensure the normalized path starts with upload dir
    if not normalized.startswith(app.config['UPLOAD_DIR']):
        return None
    return normalized

def check_file_access(file_record, user_id, required_permission='read'):
    """Check if user has access to a file."""
    if file_record['owner_id'] == user_id:
        return True
    if file_record['is_public'] and required_permission == 'read':
        return True
    db = get_db()
    share = db.execute(
        'SELECT permission FROM shares WHERE file_id = ? AND shared_with_id = ?',
        (file_record['id'], user_id)
    ).fetchone()
    if not share:
        return False
    if required_permission == 'read':
        return share['permission'] in ('read', 'write')
    return share['permission'] == 'write'

@app.route('/api/files', methods=['POST'])
@authenticate
def upload_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    safe_name = validate_filename(file.filename)
    if not safe_name:
        return jsonify({'error': 'Invalid filename'}), 400

    # Check quota
    db = get_db()
    used_space = db.execute(
        'SELECT COALESCE(SUM(file_size), 0) as total FROM files WHERE owner_id = ?',
        (g.user['id'],)
    ).fetchone()['total']

    file_content = file.read()
    if used_space + len(file_content) > g.user['storage_quota']:
        return jsonify({'error': 'Storage quota exceeded'}), 413

    storage_path = resolve_storage_path(g.user['id'], safe_name)
    if not storage_path:
        return jsonify({'error': 'Invalid storage path'}), 400

    os.makedirs(os.path.dirname(storage_path), exist_ok=True)

    content_hash = hashlib.sha256(file_content).hexdigest()
    with open(storage_path, 'wb') as f:
        f.write(file_content)

    db.execute(
        'INSERT INTO files (owner_id, filename, storage_path, file_size, content_hash) VALUES (?, ?, ?, ?, ?)',
        (g.user['id'], safe_name, storage_path, len(file_content), content_hash)
    )
    db.commit()

    return jsonify({'message': 'File uploaded', 'filename': safe_name, 'size': len(file_content)}), 201

@app.route('/api/files/<int:file_id>', methods=['GET'])
@authenticate
def download_file(file_id):
    db = get_db()
    file_record = db.execute(
        'SELECT * FROM files WHERE id = ?', (file_id,)
    ).fetchone()

    if not file_record:
        return jsonify({'error': 'File not found'}), 404

    if not check_file_access(dict(file_record), g.user['id']):
        return jsonify({'error': 'Access denied'}), 403

    # Verify file still exists and hasn't been tampered with
    storage_path = file_record['storage_path']
    if not os.path.isfile(storage_path):
        return jsonify({'error': 'File not found on disk'}), 404

    with open(storage_path, 'rb') as f:
        content = f.read()
    current_hash = hashlib.sha256(content).hexdigest()
    if not hmac.compare_digest(current_hash, file_record['content_hash']):
        return jsonify({'error': 'File integrity check failed'}), 500

    return send_file(
        storage_path,
        as_attachment=True,
        download_name=file_record['filename']
    )

@app.route('/api/files/<int:file_id>/share', methods=['POST'])
@authenticate
def share_file(file_id):
    db = get_db()
    file_record = db.execute(
        'SELECT * FROM files WHERE id = ? AND owner_id = ?',
        (file_id, g.user['id'])
    ).fetchone()

    if not file_record:
        return jsonify({'error': 'File not found or not owned by you'}), 404

    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Username required'}), 400

    permission = data.get('permission', 'read')
    if permission not in ('read', 'write'):
        return jsonify({'error': 'Invalid permission'}), 400

    target_user = db.execute(
        'SELECT id FROM users WHERE username = ? AND is_active = 1',
        (data['username'],)
    ).fetchone()

    if not target_user:
        return jsonify({'error': 'User not found'}), 404

    db.execute(
        'INSERT OR REPLACE INTO shares (file_id, shared_with_id, permission) VALUES (?, ?, ?)',
        (file_id, target_user['id'], permission)
    )
    db.commit()

    return jsonify({'message': f'File shared with {data["username"]}'}), 200

@app.route('/api/files/export', methods=['GET'])
@authenticate
def export_files():
    """Export file listing. Supports custom path for export location."""
    db = get_db()

    # Get user's files
    files = db.execute(
        'SELECT id, filename, file_size, created_at, is_public FROM files WHERE owner_id = ?',
        (g.user['id'],)
    ).fetchall()

    export_format = request.args.get('format', 'json')
    if export_format not in ('json', 'csv'):
        return jsonify({'error': 'Unsupported format'}), 400

    # Optional: serve a specific file by path for backward compatibility
    file_path = request.args.get('path')
    if file_path:
        # Validate: must not contain traversal sequences
        if '..' in file_path or BLOCKED_PATTERNS.search(file_path):
            return jsonify({'error': 'Invalid path'}), 400

        # Resolve against user's upload directory
        user_dir = os.path.join(app.config['UPLOAD_DIR'], str(g.user['id']))
        requested_path = os.path.join(user_dir, file_path)

        # Normalize and verify containment
        normalized_requested = os.path.normpath(requested_path)
        normalized_base = os.path.normpath(user_dir)

        if not normalized_requested.startswith(normalized_base + os.sep):
            return jsonify({'error': 'Access denied'}), 403

        if not os.path.isfile(normalized_requested):
            return jsonify({'error': 'File not found'}), 404

        return send_file(normalized_requested, as_attachment=True)

    file_list = [dict(row) for row in files]
    return jsonify({'files': file_list})

@app.route('/api/public/<path:filepath>', methods=['GET'])
def serve_public_file(filepath):
    """Serve publicly shared files by their storage path."""
    # Block obvious traversal attempts
    if '..' in filepath:
        abort(400)

    # Construct the full path from the public files directory
    public_base = os.path.join(app.config['UPLOAD_DIR'], 'public')

    # Use os.path.join to safely combine base and user-provided path
    target_path = os.path.join(public_base, filepath)

    # Verify the file is actually in our public directory
    real_target = os.path.realpath(target_path)
    real_base = os.path.realpath(public_base)

    if not real_target.startswith(real_base):
        abort(403)

    # Verify this file is marked as public in the database
    db = get_db()
    file_record = db.execute(
        'SELECT * FROM files WHERE storage_path = ? AND is_public = 1',
        (real_target,)
    ).fetchone()

    if not file_record:
        abort(404)

    return send_file(real_target, as_attachment=True)

@app.route('/api/admin/preview', methods=['GET'])
@authenticate
def admin_preview():
    """Admin endpoint to preview any file by path (admin only)."""
    db = get_db()
    # Check admin status
    admin_check = db.execute(
        'SELECT 1 FROM user_roles WHERE user_id = ? AND role = ?',
        (g.user['id'], 'admin')
    ).fetchone()

    if not admin_check:
        return jsonify({'error': 'Admin access required'}), 403

    file_path = request.args.get('file')
    if not file_path:
        return jsonify({'error': 'File path required'}), 400

    # Sanitize: remove traversal patterns
    if '..' in file_path or '\x00' in file_path:
        return jsonify({'error': 'Invalid path'}), 400

    # Build safe path within uploads directory
    base_dir = app.config['UPLOAD_DIR']
    safe_path = os.path.join(base_dir, file_path)

    # Normalize to handle any edge cases
    final_path = os.path.normpath(safe_path)

    # Containment check
    if not final_path.startswith(os.path.normpath(base_dir)):
        return jsonify({'error': 'Path outside allowed directory'}), 403

    if not os.path.isfile(final_path):
        return jsonify({'error': 'File not found'}), 404

    # Return first 1KB as preview
    with open(final_path, 'rb') as f:
        preview = f.read(1024)

    return jsonify({
        'path': final_path,
        'preview': preview.hex(),
        'size': os.path.getsize(final_path)
    })

@app.route('/api/files/batch', methods=['POST'])
@authenticate
def batch_download():
    """Download multiple files as a batch operation."""
    data = request.get_json()
    if not data or 'files' not in data:
        return jsonify({'error': 'File list required'}), 400

    if not isinstance(data['files'], list) or len(data['files']) > 20:
        return jsonify({'error': 'Invalid file list (max 20)'}), 400

    results = []
    db = get_db()

    for file_entry in data['files']:
        if isinstance(file_entry, int):
            # File ID mode
            file_record = db.execute(
                'SELECT * FROM files WHERE id = ?', (file_entry,)
            ).fetchone()
            if file_record and check_file_access(dict(file_record), g.user['id']):
                results.append({
                    'id': file_record['id'],
                    'filename': file_record['filename'],
                    'size': file_record['file_size']
                })
        elif isinstance(file_entry, str):
            # Filename mode - resolve from user's directory
            safe_name = validate_filename(file_entry)
            if safe_name:
                storage_path = resolve_storage_path(g.user['id'], safe_name)
                if storage_path and os.path.isfile(storage_path):
                    results.append({
                        'filename': safe_name,
                        'path': storage_path,
                        'size': os.path.getsize(storage_path)
                    })

    return jsonify({'files': results, 'count': len(results)})

